// news-image-20261119: a one-image front page for Thursday 19 November 2026.
//
// The entry is a program that writes one image to /output/entry.png. The
// image itself lives in this repository as entry.png (generated by the
// agent with an image model from the day's verified reporting; see
// generate.md for the prompt and the two attempts), so this program only
// has to copy it into place. No network, no randomness, no clock: two
// runs write the same bytes every time.
//
// Run it outside the grader with:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { copyFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';

const outDir = process.env.MAKEFUN_OUTPUT_DIR?.trim() || '/output';
mkdirSync(outDir, { recursive: true });

const source = new URL('./entry.png', import.meta.url);
copyFileSync(source, join(outDir, 'entry.png'));
